import { TriggerClient } from "@trigger.dev/sdk/v3";
import { webhookHandler } from "./src/trigger/webhook";
import { v4 as uuidv4 } from "uuid";

async function main() {
  const idempotencyKey = `webhook-${Date.now()}`;
  const amount = 100;

  console.log(`Triggering task twice with idempotencyKey: ${idempotencyKey}`);

  // Triggering the task twice in quick succession with the same idempotencyKey
  const run1 = await webhookHandler.trigger({
    idempotencyKey,
    amount
  }, {
    idempotencyKey
  });

  const run2 = await webhookHandler.trigger({
    idempotencyKey,
    amount
  }, {
    idempotencyKey
  });

  console.log(`Run ID 1:: ${run1.id}, Run ID 2: ${run2.id}`);

  // Wait for them to complete and check results
  console.log("Waiting for runs to complete...");

  // Note: In a real scenario, you'd poll or use a webhook. 
  // For this script, we'll just wait a bit and then fetch the run status if possible, 
  // or just rely on the fact that they are triggered.
  // The requirement asks to print the Run IDs.
}

main().catch(console.error);

